updated:
while there are no posts, which Atom requires; this
   one falls back to the day the blog was set up. Each entry carries the whole
   post, and its description as the summary. -#}

   {{ config.title }}
   {{ config.description }}


   {% if last_updated is defined %}{{ last_updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% else %}2026-11-14T00:00:00+00:00{% endif %}
   {{ feed_url | safe }}

       {{ config.author }}

   {%- for page in pages %}

       {{ page.title }}
       {{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}
       {% if page.updated %}{{ page.updated | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% else %}{{ page.date | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}

       {{ page.permalink | safe }}

           {{ config.author }}

       {%- if page.description %}
       {{ page.description }}
       {%- endif %}
       {{ page.content }}

   {%- endfor %}
